// European Portuguese texts of catalog.mjs: [English text, Portuguese text], in catalog order. The English side must
// match the T() text exactly (the build names any text without a translation and any entry whose English text changed
// or went away). Terms follow the app (src/Filee.App/Assets/i18n/pt-PT.json): ficheiro (file), predefinição (preset),
// motor / motores opcionais (engines), barra circular (donut), pastas monitorizadas (watch folders), zona de largada
// (drop zone), descarregar (download), guardar (save), preset names as in the app (Comprimir PDF, Vetorizar para SVG…).

import { dictionary } from './dictionary.mjs';

export default dictionary([
  // Engines
  [`video and audio, subtitle extraction and saving HEIC`,
    `vídeo e áudio, extração de legendas e gravação em HEIC`],
  [`older office formats such as DOC, PPT and ODT`,
    `formatos de escritório mais antigos, como DOC, PPT e ODT`],
  [`rare e-book formats and MOBI/AZW3 output`,
    `formatos raros de livros digitais e saída em MOBI/AZW3`],
  [`EPS and PostScript`,
    `EPS e PostScript`],
  [`LaTeX, Org, AsciiDoc and other markup, Word → Markdown and Markdown → slides`,
    `LaTeX, Org, AsciiDoc e outras linguagens de marcação, Word → Markdown e Markdown → diapositivos`],

  // Options
  [`quality`, `qualidade`],
  [`Adjustable quality for JPG, WEBP and AVIF: JPG saves at 90 % by default, and a JPG 70 % preset makes smaller files.`,
    `Qualidade ajustável para JPG, WEBP e AVIF: o JPG é guardado a 90% por omissão, e uma predefinição JPG 70% cria ficheiros mais pequenos.`],
  [`resize`, `redimensionar`],
  [`Resize while converting, by percentage (for example half size) or to a maximum long edge.`,
    `Redimensiona durante a conversão, por percentagem (por exemplo, metade do tamanho) ou até um limite para o lado maior.`],
  [`DPI`, `DPI`],
  [`Set the DPI written into the image, for example 300 for print.`,
    `Define o DPI gravado na imagem, por exemplo, 300 para impressão.`],
  [`grayscale`, `escala de cinzentos`],
  [`A grayscale preset makes black-and-white copies.`,
    `Uma predefinição de escala de cinzentos cria cópias a preto e branco.`],
  [`metadata`, `metadados`],
  [`Metadata (EXIF, XMP, colour profile) is kept by default and can be removed for privacy.`,
    `Os metadados (EXIF, XMP, perfil de cor) são mantidos por omissão e podem ser removidos por privacidade.`],
  [`ICO sizes`, `tamanhos de ICO`],
  [`ICO files hold 256, 128, 64, 48, 32 and 16 px by default; the sizes can be changed in the preset.`,
    `Os ficheiros ICO contêm 256, 128, 64, 48, 32 e 16 px por omissão; os tamanhos podem ser alterados na predefinição.`],
  [`TIFF compression`, `compressão TIFF`],
  [`TIFF compression can be chosen (LZW by default).`,
    `Podes escolher a compressão TIFF (LZW por omissão).`],
  [`white background`, `fundo branco`],
  [`JPG has no transparency, so transparent areas are filled with white.`,
    `O JPG não admite transparência, pelo que as áreas transparentes são preenchidas a branco.`],
  [`merge into one PDF`, `juntar num PDF`],
  [`The merge preset combines all dropped files into one PDF.`,
    `A predefinição Juntar PDF reúne todos os ficheiros que largares num único PDF.`],
  [`split pages`, `dividir páginas`],
  [`The split preset saves every page as its own PDF in a subfolder.`,
    `A predefinição Dividir PDF guarda cada página como um PDF à parte, numa subpasta.`],
  [`rotate & flip`, `rodar e inverter`],
  [`Rotate and flip presets turn images left, right or 180° and mirror them, after the photo's own orientation.`,
    `As predefinições Rodar e Inverter rodam as imagens para a esquerda, para a direita ou 180° e invertem-nas, depois de aplicada a orientação da própria fotografia.`],
  [`Trace to SVG`, `Vetorizar para SVG`],
  [`Two presets trace a picture into vector shapes: Trace to SVG in up to 64 colours, and Line art to SVG in black for logos, signatures and scans. No other program is needed.`,
    `Duas predefinições transformam uma imagem em formas vetoriais: Vetorizar para SVG, com até 64 cores, e Traços para SVG, a preto, para logótipos, assinaturas e digitalizações. Não é preciso mais nenhum programa.`],
  [`remove background`, `remover fundo`],
  [`The Remove background preset makes a plain backdrop transparent: the paper behind a signature or stamp, the backdrop of a logo.`,
    `A predefinição Remover fundo torna transparente um fundo simples: o papel atrás de uma assinatura ou carimbo, o fundo de um logótipo.`],
  [`page ranges`, `intervalos de páginas`],
  [`Page ranges such as 1-3,5 limit the conversion to the pages you need.`,
    `Intervalos de páginas como 1-3,5 limitam a conversão às páginas de que precisas.`],
  [`render DPI`, `DPI de renderização`],
  [`Pages are rendered at 150 DPI by default; choose 300 DPI for print quality.`,
    `As páginas são renderizadas a 150 DPI por omissão; escolhe 300 DPI para qualidade de impressão.`],
  [`one long image`, `uma imagem longa`],
  [`The Long image preset stacks all pages into one tall image, e.g. to post a whole document at once.`,
    `A predefinição Imagem longa empilha todas as páginas numa única imagem alta, por exemplo, para publicar um documento inteiro de uma só vez.`],
  [`compress PDF`, `comprimir PDF`],
  [`The Compress PDF preset makes a PDF smaller while it stays a PDF: pictures are scaled down to 72, 150 or 300 dpi and photos saved again as JPEG, while text, fonts, links, bookmarks and forms stay. A PDF that can't get smaller is left as it was. With Ghostscript installed, Filee can try it too and keep the smaller result.`,
    `A predefinição Comprimir PDF torna um PDF mais pequeno sem que deixe de ser um PDF: as imagens são reduzidas para 72, 150 ou 300 dpi e as fotografias voltam a ser guardadas em JPEG, enquanto o texto, os tipos de letra, as ligações, os marcadores e os formulários se mantêm. Um PDF que não consiga ficar mais pequeno fica como estava. Com o Ghostscript instalado, o Filee também o experimenta e fica com o resultado mais pequeno.`],
  [`a picture per slide`, `uma imagem por diapositivo`],
  [`PPTX (slides) puts a picture of each page on its own slide, at the page's size, with the page's text in the speaker notes. The slides look exactly like the PDF but aren't editable; convert to DOCX for editable text.`,
    `O PPTX (diapositivos) coloca uma imagem de cada página num diapositivo próprio, ao tamanho da página, com o texto da página nas notas do apresentador. Os diapositivos ficam iguais ao PDF, mas não são editáveis; converte para DOCX se quiseres texto editável.`],
  [`vector PDF`, `PDF vetorial`],
  [`The PDF stays vector, so it is sharp at any zoom and in print.`,
    `O PDF continua vetorial, pelo que fica nítido com qualquer zoom e na impressão.`],
  [`editable`, `editável`],
  [`The result has real text and paragraphs you can edit, not pictures of pages.`,
    `O resultado tem texto e parágrafos verdadeiros, que podes editar, e não imagens das páginas.`],
  [`attachments as ZIP`, `anexos em ZIP`],
  [`Attachments can be saved separately as one ZIP.`,
    `Os anexos podem ser guardados à parte, num único ZIP.`],
  [`one CSV per sheet`, `um CSV por folha`],
  [`Workbooks with several sheets give one CSV per sheet.`,
    `Os livros com várias folhas dão um CSV por folha.`],
  [`layout kept`, `disposição mantida`],
  [`Keeps page size and margins, headers and footers with page numbers, tables, text boxes, shapes and pictures.`,
    `Mantém o tamanho da página e as margens, os cabeçalhos e rodapés com números de página, as tabelas, as caixas de texto, as formas e as imagens.`],
  [`no Office needed`, `sem precisar do Office`],
  [`No Microsoft Office or LibreOffice needed.`,
    `Não precisa do Microsoft Office nem do LibreOffice.`],
  [`no Hancom Office needed`, `sem precisar do Hancom Office`],
  [`No Hancom Office and no approval dialog.`,
    `Sem Hancom Office e sem caixa de diálogo de aprovação.`],
  [`no AutoCAD needed`, `sem precisar do AutoCAD`],
  [`No AutoCAD or DWG viewer needed.`,
    `Não precisa do AutoCAD nem de um visualizador de DWG.`],
  [`no re-encoding`, `sem recodificação`],
  [`When the new format can hold the video and sound as they are (an iPhone MOV → MP4), they are only rewrapped: no quality lost, HDR kept, done in seconds.`,
    `Quando o novo formato aceita o vídeo e o som tal como estão (um MOV de iPhone → MP4), só muda o contentor: sem perda de qualidade, com o HDR mantido e em poucos segundos.`],
  [`720p option`, `opção 720p`],
  [`The MP4 720p preset shrinks large videos for sharing.`,
    `A predefinição MP4 720p reduz vídeos grandes para os partilhares.`],
  [`extract audio`, `extrair áudio`],
  [`Only the sound is saved, without the video track.`,
    `Só o som é guardado, sem a faixa de vídeo.`],
  [`MP3 128k`, `MP3 128k`],
  [`The MP3 128k preset makes smaller files, ideal for speech.`,
    `A predefinição MP3 128k cria ficheiros mais pequenos, ideais para voz.`],
  [`extract`, `extrair`],
  [`The extract preset unpacks an archive into a folder instead.`,
    `Já a predefinição Extrair descomprime o ficheiro numa pasta.`],
  [`pack into one ZIP`, `comprimir num ZIP`],
  [`Any selection of files can be packed into one ZIP.`,
    `Qualquer seleção de ficheiros pode ser comprimida num único ZIP.`],
  [`DRM-free books`, `livros sem DRM`],
  [`Works with DRM-free books only.`,
    `Funciona apenas com livros sem DRM.`],
  [`ALAC in M4A`, `ALAC em M4A`],
  [`M4A can hold lossless ALAC as well as AAC.`,
    `O M4A pode conter ALAC sem perdas, além de AAC.`],
  [`HEVC / AV1`, `HEVC / AV1`],
  [`Video presets can encode HEVC (H.265) or AV1 for smaller files, keeping 10-bit and HDR video.`,
    `As predefinições de vídeo podem codificar em HEVC (H.265) ou AV1 para obter ficheiros mais pequenos, mantendo o vídeo de 10 bits e HDR.`],
  [`hardware encoding`, `codificação por hardware`],
  [`Turn on Use hardware acceleration in a video preset to encode H.264 and HEVC on the graphics chip (NVENC, Quick Sync, AMF, VideoToolbox or VA-API): much faster and lighter on power, slightly larger at the same quality. It is off by default, and without a usable chip the video is encoded as before.`,
    `Ativa Utilizar aceleração por hardware numa predefinição de vídeo para codificar H.264 e HEVC no chip gráfico (NVENC, Quick Sync, AMF, VideoToolbox ou VA-API): muito mais rápido e com menor consumo de energia, com ficheiros um pouco maiores para a mesma qualidade. Vem desativado de origem e, sem um chip compatível, o vídeo é codificado como antes.`],
  [`every frame`, `todos os fotogramas`],
  [`Usually a video gives one still frame. The Extract frames presets, or Save every frame of a video in a PNG or JPG preset, save every frame (or every Nth) as pictures in a folder next to the video.`,
    `Normalmente, um vídeo dá uma única imagem fixa. As predefinições Extrair fotogramas, ou a opção Guardar todos os fotogramas de um vídeo numa predefinição PNG ou JPG, guardam todos os fotogramas (ou um a cada N) como imagens numa pasta junto ao vídeo.`],
  [`extract subtitles`, `extrair legendas`],
  [`The Extract subtitles preset on the video donut saves the first text subtitle track of a video as SRT.`,
    `A predefinição Extrair legendas, na barra circular de vídeo, guarda a primeira faixa de legendas em texto de um vídeo como SRT.`],
  [`saved as UTF-8`, `guardado em UTF-8`],
  [`Results are saved as UTF-8. Korean files saved in CP949 (EUC-KR) are detected and read correctly.`,
    `Os resultados são guardados em UTF-8. Os ficheiros coreanos guardados em CP949 (EUC-KR) são detetados e lidos corretamente.`],
  [`tables to CSV / Excel`, `tabelas para CSV / Excel`],
  [`Data that is a table (a list of records) also converts to and from CSV and Excel.`,
    `Os dados em forma de tabela (uma lista de registos) também se convertem de e para CSV e Excel.`],
  [`picture preview`, `pré-visualização em imagem`],
  [`PNG or JPG gives a shaded picture of the model, seen from the front right and above.`,
    `O PNG ou o JPG dá uma imagem sombreada do modelo, vista de frente, pela direita e de cima.`],
  [`colours and textures`, `cores e texturas`],
  [`Colours, textures and materials are kept where the target format can hold them. STL keeps only the shape.`,
    `As cores, as texturas e os materiais são mantidos quando o formato de destino os admite. O STL mantém só a forma.`],
  [`HDR tone-mapped`, `HDR com mapeamento de tons`],
  [`HDR screenshots that Windows saves as JPEG XR are tone-mapped to normal brightness instead of being clipped.`,
    `As capturas de ecrã HDR que o Windows guarda em JPEG XR passam por um mapeamento de tons para o brilho normal, em vez de ficarem queimadas.`],
  [`Live Photo video`, `vídeo da Live Photo`],
  [`The Extract Live Photo video preset saves the video of an iPhone Live Photo (a LIVP from iCloud, or a photo with its MOV) or an Android Motion Photo as MP4 or MOV. The other way round, the Live Photo (iPhone) and Motion Photo (Android) presets turn a short clip of a video into a moving photo; that is still experimental.`,
    `A predefinição Extrair vídeo da Live Photo guarda o vídeo de uma Live Photo de iPhone (um LIVP do iCloud ou uma fotografia com o respetivo MOV) ou de uma Motion Photo de Android em MP4 ou MOV. No sentido inverso, as predefinições Live Photo (iPhone) e Motion Photo (Android) transformam um excerto curto de um vídeo numa fotografia com movimento; isto ainda é experimental.`],
  [`WGS 84 longitude / latitude`, `longitude / latitude WGS 84`],
  [`Results are always in longitude and latitude (WGS 84). Shapefiles in UTM, Web Mercator, Lambert or Albers are converted, so they open in the right place; converting a file to its own format reprojects it.`,
    `Os resultados estão sempre em longitude e latitude (WGS 84). Os Shapefiles em UTM, Web Mercator, Lambert ou Albers são convertidos e abrem no sítio certo; converter um ficheiro para o seu próprio formato reprojeta-o.`],
  [`save as ZIP`, `guardar em ZIP`],
  [`A Shapefile is five files (.shp, .shx, .dbf, .prj and .cpg). With Save the result as a ZIP in a preset, or for every geospatial result in the settings, they travel together in one ZIP.`,
    `Um Shapefile é composto por cinco ficheiros (.shp, .shx, .dbf, .prj e .cpg). Com Guardar o resultado em ZIP numa predefinição, ou para todos os resultados geoespaciais nas definições, ficam juntos num único ZIP.`],
  [`Canon CR2 RAW photo`, `Fotografia RAW Canon CR2`],
  [`CR2 is the RAW photo format Canon DSLRs used for many years (newer Canon models write CR3). It stores the unprocessed sensor data, which leaves plenty of room for editing.`,
    `O CR2 é o formato de fotografia RAW que as DSLR da Canon usaram durante muitos anos (os modelos mais recentes da Canon gravam CR3). Guarda os dados em bruto do sensor, o que deixa bastante margem para edição.`],
  [`Nikon NEF RAW photo`, `Fotografia RAW Nikon NEF`],
  [`NEF is Nikon's RAW photo format, used by Nikon DSLRs and Z mirrorless cameras. Like other RAW files it holds unprocessed sensor data and is several times larger than a JPG.`,
    `O NEF é o formato de fotografia RAW da Nikon, usado pelas DSLR e pelas câmaras mirrorless Z da Nikon. Tal como outros ficheiros RAW, guarda os dados em bruto do sensor e é várias vezes maior do que um JPG.`],

  // Images
  [`Images`, `Imagens`],
  [`images`, `imagens`],
  [`Photos and graphics, including iPhone HEIC and Live Photos, Photoshop PSD, camera RAW from all major brands, animated APNG, DICOM and the HDR screenshots of Windows (JPEG XR). Resize, rotate, set quality and DPI or strip metadata while converting, or trace a picture into an SVG.`,
    `Fotografias e gráficos, incluindo HEIC e Live Photos de iPhone, PSD do Photoshop, RAW de câmaras de todas as grandes marcas, APNG animado, DICOM e as capturas de ecrã HDR do Windows (JPEG XR). Redimensiona, roda, define a qualidade e o DPI ou remove metadados durante a conversão, ou vetoriza uma imagem para SVG.`],
  [`JPEG image`, `Imagem JPEG`],
  [`JPEG is the most widely used photo format. Its lossy compression keeps files small, but every save at lower quality discards some detail, and it has no transparency.`,
    `O JPEG é o formato de fotografia mais utilizado. A sua compressão com perdas mantém os ficheiros pequenos, mas cada gravação com qualidade inferior descarta algum detalhe, e não admite transparência.`],
  [`PNG image`, `Imagem PNG`],
  [`PNG is a lossless image format with transparency, ideal for screenshots, logos and graphics with sharp edges. Photos saved as PNG are usually much larger than JPG.`,
    `O PNG é um formato de imagem sem perdas e com transparência, ideal para capturas de ecrã, logótipos e gráficos com contornos nítidos. As fotografias guardadas em PNG costumam ficar muito maiores do que em JPG.`],
  [`WebP image`, `Imagem WebP`],
  [`WebP is Google's image format for the web. It supports lossy and lossless compression and transparency and is usually smaller than JPG or PNG, but some editors and upload forms still don't accept it.`,
    `O WebP é o formato de imagem da Google para a Web. Suporta compressão com e sem perdas e transparência, e costuma ser mais pequeno do que o JPG ou o PNG, mas alguns editores e formulários de envio ainda não o aceitam.`],
  [`AVIF image`, `Imagem AVIF`],
  [`AVIF is a modern image format based on the AV1 video codec. It compresses better than JPG and WebP, but support in older software and devices is still limited.`,
    `O AVIF é um formato de imagem moderno baseado no codec de vídeo AV1. Comprime melhor do que o JPG e o WebP, mas o suporte em programas e dispositivos mais antigos ainda é limitado.`],
  [`HEIC / HEIF image`, `Imagem HEIC / HEIF`],
  [`HEIC (HEIF) is the photo format iPhones and iPads use by default. Photos are often about half the size of a JPG, but many Windows apps, websites and older devices can't open them.`,
    `O HEIC (HEIF) é o formato de fotografia que os iPhones e iPads usam por omissão. As fotografias têm muitas vezes cerca de metade do tamanho de um JPG, mas muitas aplicações do Windows, sites e dispositivos mais antigos não as conseguem abrir.`],
  [`GIF image / animation`, `Imagem / animação GIF`],
  [`GIF is an old image format limited to 256 colours that supports simple animation. It is still the universal way to share short silent loops in chats, documents and bug reports.`,
    `O GIF é um formato de imagem antigo, limitado a 256 cores, que suporta animações simples. Continua a ser a forma universal de partilhar pequenas animações em ciclo, sem som, em conversas, documentos e relatórios de erros.`],
  [`Windows icon`, `Ícone do Windows`],
  [`ICO is the Windows icon format. One ICO file holds the same picture at several sizes (for example 16, 32, 48 and 256 pixels), so it looks sharp everywhere from the taskbar to website favicons.`,
    `O ICO é o formato de ícone do Windows. Um único ficheiro ICO guarda a mesma imagem em vários tamanhos (por exemplo, 16, 32, 48 e 256 píxeis), para que fique nítida em todo o lado, da barra de tarefas aos favicons dos sites.`],
  [`Photoshop document`, `Documento do Photoshop`],
  [`PSD is Adobe Photoshop's native format. It keeps layers, masks and adjustment settings, so it is great for editing but can't be opened by most viewers or websites.`,
    `O PSD é o formato nativo do Adobe Photoshop. Mantém camadas, máscaras e ajustes, pelo que é ótimo para edição, mas a maioria dos visualizadores e sites não o consegue abrir.`],
  [`macOS icon`, `Ícone do macOS`],
  [`ICNS is the icon format of macOS. Like ICO it bundles several sizes of one image, up to 1024×1024 for Retina displays, and is used for app icons on the Mac.`,
    `O ICNS é o formato de ícone do macOS. Tal como o ICO, reúne vários tamanhos de uma imagem, até 1024×1024 para ecrãs Retina, e é usado nos ícones das aplicações no Mac.`],
  [`Camera RAW`, `RAW de câmara`],
  [`Windows only`, `apenas no Windows`],
  [`the photo of the Live Photo`, `a fotografia da Live Photo`],
  [`the video of the Live Photo`, `o vídeo da Live Photo`],

  // Vector graphics
  [`Vector graphics`, `Gráficos vetoriais`],
  [`vector graphics`, `gráficos vetoriais`],
  [`SVG, Windows metafiles, Illustrator, EPS/PostScript and drawings from CorelDRAW, Visio and LibreOffice Draw. SVG also becomes DXF or DWG for CAD.`,
    `SVG, metaficheiros do Windows, Illustrator, EPS/PostScript e desenhos do CorelDRAW, do Visio e do LibreOffice Draw. O SVG também passa a DXF ou DWG para CAD.`],
  [`SVG vector graphic`, `Gráfico vetorial SVG`],
  [`SVG is an XML-based vector graphics format. Shapes and text stay sharp at any size, which makes it ideal for logos and icons on the web, but many apps and upload forms only accept pixel images.`,
    `O SVG é um formato de gráficos vetoriais baseado em XML. As formas e o texto ficam nítidos em qualquer tamanho, o que o torna ideal para logótipos e ícones na Web, mas muitas aplicações e formulários de envio só aceitam imagens em píxeis.`],
  [`Encapsulated PostScript`, `PostScript encapsulado`],
  [`EPS is a vector format from print and design work, often used for logos and illustrations sent to print shops. Most modern apps can't show it without a PostScript interpreter.`,
    `O EPS é um formato vetorial do mundo da impressão e do design, muito usado para logótipos e ilustrações enviados para gráficas. A maioria das aplicações modernas não o consegue mostrar sem um interpretador de PostScript.`],
  [`AI files saved with PDF content (Illustrator's default)`,
    `ficheiros AI guardados com conteúdo PDF (a predefinição do Illustrator)`],

  // PDF
  [`PDF`, `PDF`],
  [`Turn PDFs into images, editable Word or HWPX documents, PowerPoint slides, text or a comic archive, and merge, split, compress or pick pages.`,
    `Transforma PDF em imagens, documentos editáveis do Word ou HWPX, diapositivos do PowerPoint, texto ou um ficheiro de banda desenhada, e junta, divide, comprime ou escolhe páginas.`],
  [`PDF document`, `Documento PDF`],
  [`PDF is the standard for sharing documents that must look the same everywhere. Fonts, layout and images are fixed, and it opens on any device. That also makes PDFs hard to edit.`,
    `O PDF é a norma para partilhar documentos que têm de ter o mesmo aspeto em todo o lado. Os tipos de letra, a disposição e as imagens são fixos, e abre em qualquer dispositivo. É também por isso que os PDF são difíceis de editar.`],
  [`one page`, `uma página`],

  // Documents
  [`Documents`, `Documentos`],
  [`documents`, `documentos`],
  [`Word documents without Microsoft Office, Chinese OFD e-invoices, older and rare word-processor formats with the optional LibreOffice engine, and saved e-mails (EML and Outlook MSG).`,
    `Documentos do Word sem o Microsoft Office, faturas eletrónicas chinesas em OFD, formatos de processadores de texto antigos e raros com o motor opcional LibreOffice, e e-mails guardados (EML e MSG do Outlook).`],
  [`Word document`, `Documento do Word`],
  [`DOCX is the Microsoft Word format since Word 2007 (Office Open XML). It is the most common format for editable documents such as reports, letters and forms.`,
    `O DOCX é o formato do Microsoft Word desde o Word 2007 (Office Open XML). É o formato mais comum para documentos editáveis, como relatórios, cartas e formulários.`],
  [`Word 97–2003 document`, `Documento do Word 97–2003`],
  [`DOC is the binary format of Word 97–2003. Old archives, official forms and legacy systems still produce it, but it is being replaced by DOCX.`,
    `O DOC é o formato binário do Word 97–2003. Arquivos antigos, formulários oficiais e sistemas legados ainda o produzem, mas está a ser substituído pelo DOCX.`],
  [`E-mail message`, `Mensagem de e-mail`],
  [`EML is a single e-mail saved as a file (MIME format), with the headers, the message and its attachments. Most mail apps, including Outlook and Thunderbird, can open it.`,
    `O EML é um único e-mail guardado como ficheiro (formato MIME), com os cabeçalhos, a mensagem e os anexos. A maioria das aplicações de e-mail, incluindo o Outlook e o Thunderbird, consegue abri-lo.`],
  [`Outlook message`, `Mensagem do Outlook`],
  [`MSG is the file Microsoft Outlook saves when you drag an e-mail out of it. Only Outlook opens it, so it is hard to read on a PC without Outlook or on a phone.`,
    `O MSG é o ficheiro que o Microsoft Outlook guarda quando arrastas um e-mail para fora dele. Só o Outlook o abre, pelo que é difícil lê-lo num computador sem o Outlook ou num telemóvel.`],

  // HWP
  [`HWP (Hangul)`, `HWP (Hangul)`],
  [`Korean HWP/HWPX`, `HWP/HWPX coreano`],
  [`Korean Hancom Hangul documents without Hancom Office: HWP ↔ HWPX, to PDF, images, Word, text, Markdown and HTML, and HWPX from Word, Excel, PowerPoint, Markdown and PDF.`,
    `Documentos coreanos do Hancom Hangul sem o Hancom Office: HWP ↔ HWPX, para PDF, imagens, Word, texto, Markdown e HTML, e HWPX a partir de Word, Excel, PowerPoint, Markdown e PDF.`],
  [`Hangul document (HWP)`, `Documento do Hangul (HWP)`],
  [`HWP is the document format of Hancom Office Hangul (한글), the standard word processor in Korean government offices, schools and many companies. Outside Korea few programs can open it.`,
    `O HWP é o formato de documento do Hancom Office Hangul (한글), o processador de texto padrão nos serviços públicos, nas escolas e em muitas empresas da Coreia. Fora da Coreia, poucos programas o conseguem abrir.`],
  [`Hangul document (HWPX)`, `Documento do Hangul (HWPX)`],
  [`HWPX is the open, XML-based format of Hancom Hangul (OWPML, Korean national standard KS X 6101). Korean public institutions are moving to it from the binary HWP format.`,
    `O HWPX é o formato aberto, baseado em XML, do Hancom Hangul (OWPML, norma nacional coreana KS X 6101). As instituições públicas coreanas estão a passar do formato binário HWP para este.`],

  // Spreadsheets
  [`Spreadsheets`, `Folhas de cálculo`],
  [`spreadsheets`, `folhas de cálculo`],
  [`Excel, OpenDocument and CSV/TSV sheets, to PDF with Excel-like page fitting or into each other, without Excel.`,
    `Folhas do Excel, OpenDocument e CSV/TSV, para PDF com o ajuste de página do Excel ou entre si, sem o Excel.`],
  [`Excel workbook`, `Livro do Excel`],
  [`XLSX is the Microsoft Excel workbook format since Excel 2007. One workbook can hold several sheets with formulas, formatting, charts and pictures.`,
    `O XLSX é o formato de livro do Microsoft Excel desde o Excel 2007. Um livro pode ter várias folhas com fórmulas, formatação, gráficos e imagens.`],
  [`Excel 97–2003 workbook`, `Livro do Excel 97–2003`],
  [`XLS is the binary workbook format of Excel 97–2003. Many older systems and bank or accounting exports still produce it.`,
    `O XLS é o formato binário de livro do Excel 97–2003. Muitos sistemas antigos e exportações de bancos ou de contabilidade ainda o produzem.`],
  [`Comma-separated values`, `Valores separados por vírgulas`],
  [`CSV is plain text with one table row per line. Every spreadsheet, database and programming language reads it, but it has no formatting, formulas or multiple sheets.`,
    `O CSV é texto simples com uma linha da tabela por linha do ficheiro. Todas as folhas de cálculo, bases de dados e linguagens de programação o leem, mas não tem formatação, fórmulas nem várias folhas.`],

  // Presentations
  [`Presentations`, `Apresentações`],
  [`presentations`, `apresentações`],
  [`PowerPoint to PDF, images and HWPX without PowerPoint; older PPT, ODP and Keynote with the optional LibreOffice engine.`,
    `PowerPoint para PDF, imagens e HWPX sem o PowerPoint; PPT antigo, ODP e Keynote com o motor opcional LibreOffice.`],
  [`PowerPoint presentation`, `Apresentação do PowerPoint`],
  [`PPTX is the Microsoft PowerPoint format since PowerPoint 2007. It holds slides with text, pictures, shapes, tables, notes and animations.`,
    `O PPTX é o formato do Microsoft PowerPoint desde o PowerPoint 2007. Contém diapositivos com texto, imagens, formas, tabelas, notas e animações.`],
  [`PowerPoint 97–2003 presentation`, `Apresentação do PowerPoint 97–2003`],
  [`PPT is the binary format of PowerPoint 97–2003. Old lecture slides and archived presentations are often still in PPT.`,
    `O PPT é o formato binário do PowerPoint 97–2003. Diapositivos de aulas antigas e apresentações arquivadas estão muitas vezes ainda em PPT.`],

  // Text & markup
  [`Text & markup`, `Texto e marcação`],
  [`text and markup`, `texto e marcação`],
  [`Plain text, Markdown, HTML and saved web pages (MHTML) to PDF, Word, HWPX and EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter and other markup use the optional Pandoc engine, which also turns Markdown into PowerPoint slides.`,
    `Texto simples, Markdown, HTML e páginas Web guardadas (MHTML) para PDF, Word, HWPX e EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter e outras linguagens de marcação usam o motor opcional Pandoc, que também transforma Markdown em diapositivos do PowerPoint.`],
  [`Plain text`, `Texto simples`],
  [`TXT is plain text without any formatting, the simplest and most portable document format. The only thing that can differ is the character encoding (UTF-8, UTF-16 or a legacy code page).`,
    `O TXT é texto simples sem qualquer formatação, o formato de documento mais simples e portátil. A única coisa que pode variar é a codificação de carateres (UTF-8, UTF-16 ou uma página de códigos antiga).`],
  [`Markdown`, `Markdown`],
  [`Markdown is a lightweight plain-text markup: # for headings, * for lists, ** for bold. It is popular for notes, README files and documentation, and is readable even without rendering.`,
    `O Markdown é uma linguagem de marcação leve em texto simples: # para títulos, * para listas, ** para negrito. É popular para notas, ficheiros README e documentação, e lê-se bem mesmo sem ser renderizado.`],
  [`Web page (HTML)`, `Página Web (HTML)`],
  [`HTML is the language of web pages. A saved .html file opens in any browser, but how it looks depends on the browser and on linked styles and images, which may be missing offline.`,
    `O HTML é a linguagem das páginas Web. Um ficheiro .html guardado abre em qualquer navegador, mas o aspeto depende do navegador e dos estilos e imagens ligados, que podem faltar sem Internet.`],
  [`LOG files and scripts (PY, PAC, BAT, COMMAND) are read as text and never run`,
    `ficheiros LOG e scripts (PY, PAC, BAT, COMMAND) são lidos como texto e nunca executados`],
  [`the saved page, with its pictures`, `a página guardada, com as imagens`],

  // Data
  [`Data`, `Dados`],
  [`data files`, `ficheiros de dados`],
  [`JSON, JSON Lines, YAML, TOML and XML into each other, and tables to and from CSV and Excel. vCard contacts to and from CSV, also from old phones. Nothing to install.`,
    `JSON, JSON Lines, YAML, TOML e XML entre si, e tabelas de e para CSV e Excel. Contactos vCard de e para CSV, também de telemóveis antigos. Nada para instalar.`],
  [`JSON data`, `Dados JSON`],
  [`JSON is the data format of the web: objects, lists, text and numbers in plain text. APIs, apps and settings files use it everywhere.`,
    `O JSON é o formato de dados da Web: objetos, listas, texto e números em texto simples. APIs, aplicações e ficheiros de definições usam-no por todo o lado.`],
  [`YAML data`, `Dados YAML`],
  [`YAML holds the same kind of data as JSON, written with indentation instead of brackets. Config files for Docker, Kubernetes, CI pipelines and many apps are YAML.`,
    `O YAML guarda o mesmo tipo de dados que o JSON, escrito com indentação em vez de chavetas. Os ficheiros de configuração do Docker, do Kubernetes, de pipelines de CI e de muitas aplicações são em YAML.`],
  [`vCard contacts`, `Contactos vCard`],
  [`vCard (.vcf) is the standard file for contacts. Phones, Outlook, Google Contacts and iCloud export address books as vCard, often many contacts in one file.`,
    `O vCard (.vcf) é o ficheiro padrão para contactos. Os telemóveis, o Outlook, o Google Contactos e o iCloud exportam listas de contactos em vCard, muitas vezes com vários contactos num só ficheiro.`],

  // E-books
  [`E-books & comics`, `Livros digitais e banda desenhada`],
  [`e-books and comics`, `livros digitais e banda desenhada`],
  [`EPUB, Kindle (MOBI, AZW, AZW3), FictionBook and comic archives (CBZ, CBR, CB7…) to PDF, EPUB, Word and more, and KEPUB for Kobo readers. DRM-free books only.`,
    `EPUB, Kindle (MOBI, AZW, AZW3), FictionBook e ficheiros de banda desenhada (CBZ, CBR, CB7…) para PDF, EPUB, Word e outros, e KEPUB para leitores Kobo. Apenas livros sem DRM.`],
  [`EPUB e-book`, `Livro digital EPUB`],
  [`EPUB is the open standard for e-books. Text reflows to fit any screen, and most e-readers and reading apps support it; Kindle accepts EPUB through Send to Kindle.`,
    `O EPUB é a norma aberta para livros digitais. O texto ajusta-se a qualquer ecrã, e a maioria dos leitores de livros digitais e aplicações de leitura suporta-o; o Kindle aceita EPUB através do Send to Kindle.`],
  [`Kindle / Mobipocket e-book`, `Livro digital Kindle / Mobipocket`],
  [`MOBI is the older Mobipocket e-book format that Amazon Kindle used for years. It is still common in older e-book collections, but Amazon has moved to AZW3/KFX and EPUB.`,
    `O MOBI é o antigo formato de livros digitais da Mobipocket que o Amazon Kindle usou durante anos. Ainda é comum em coleções de livros digitais mais antigas, mas a Amazon passou para o AZW3/KFX e o EPUB.`],

  // Video
  [`Video`, `Vídeo`],
  [`video`, `vídeo`],
  [`All common video formats to MP4 (H.264, HEVC or AV1), WebM, MOV, MKV, AVI, GIF or APNG, with a 720p option, hardware encoding on the graphics chip, audio extraction to MP3 or M4A and every frame saved as pictures. Uses the optional FFmpeg engine.`,
    `Todos os formatos de vídeo comuns para MP4 (H.264, HEVC ou AV1), WebM, MOV, MKV, AVI, GIF ou APNG, com opção de 720p, codificação por hardware no chip gráfico, extração de áudio para MP3 ou M4A e todos os fotogramas guardados como imagens. Usa o motor opcional FFmpeg.`],
  [`MPEG-4 video`, `Vídeo MPEG-4`],
  [`MP4 (MPEG-4 Part 14) is the most compatible video format. It plays on phones, TVs, browsers and every video site, usually with H.264 or H.265 video and AAC audio.`,
    `O MP4 (MPEG-4 Parte 14) é o formato de vídeo mais compatível. É reproduzido em telemóveis, televisores, navegadores e todos os sites de vídeo, normalmente com vídeo H.264 ou H.265 e áudio AAC.`],
  [`QuickTime movie`, `Filme QuickTime`],
  [`MOV is Apple's QuickTime video format, used by iPhones and Macs. It usually contains H.264 or HEVC video, but some editors, TVs and websites handle MP4 better.`,
    `O MOV é o formato de vídeo QuickTime da Apple, usado pelos iPhones e Macs. Normalmente contém vídeo H.264 ou HEVC, mas alguns editores, televisores e sites lidam melhor com o MP4.`],
  [`Matroska video`, `Vídeo Matroska`],
  [`MKV (Matroska) is a flexible open container that can hold many video, audio and subtitle tracks. It is popular for films and recordings, but phones, TVs and editors don't always play it.`,
    `O MKV (Matroska) é um contentor aberto e flexível que pode conter muitas faixas de vídeo, áudio e legendas. É popular para filmes e gravações, mas os telemóveis, televisores e editores nem sempre o reproduzem.`],
  [`WebM video`, `Vídeo WebM`],
  [`WebM is an open video format made for browsers (VP8/VP9 or AV1 video with Vorbis or Opus audio). Screen recordings and downloads are often WebM, but many editors and devices expect MP4.`,
    `O WebM é um formato de vídeo aberto feito para navegadores (vídeo VP8/VP9 ou AV1 com áudio Vorbis ou Opus). As gravações de ecrã e as transferências estão muitas vezes em WebM, mas muitos editores e dispositivos esperam MP4.`],
  [`AVI video`, `Vídeo AVI`],
  [`AVI is Microsoft's video container from the 1990s. Camcorders, older cameras and archives still hold AVI files, which are often large and poorly supported on phones.`,
    `O AVI é o contentor de vídeo da Microsoft dos anos 90. Câmaras de vídeo, câmaras antigas e arquivos ainda guardam ficheiros AVI, que costumam ser grandes e ter pouco suporte nos telemóveis.`],
  [`one still frame or every frame`, `uma imagem fixa ou todos os fotogramas`],

  // Audio
  [`Audio`, `Áudio`],
  [`audio`, `áudio`],
  [`Music, recordings and voice memos to MP3, M4A, WAV, FLAC, OGG, Opus, AAC or lossless WavPack and TTA. APE, DSD and DTS are read too. Uses the optional FFmpeg engine.`,
    `Músicas, gravações e memorandos de voz para MP3, M4A, WAV, FLAC, OGG, Opus, AAC ou WavPack e TTA sem perdas. APE, DSD e DTS também são lidos. Usa o motor opcional FFmpeg.`],
  [`MP3 audio`, `Áudio MP3`],
  [`MP3 is the classic compressed audio format. Practically every player, car stereo and phone plays it, which makes it the safest choice for sharing music, podcasts and recordings.`,
    `O MP3 é o formato clássico de áudio comprimido. Praticamente todos os leitores, autorrádios e telemóveis o reproduzem, o que faz dele a escolha mais segura para partilhar músicas, podcasts e gravações.`],
  [`MPEG-4 audio`, `Áudio MPEG-4`],
  [`M4A is an MPEG-4 audio file, usually AAC, used by iTunes, iPhone voice memos and many recorders. It sounds good at small sizes, but some players and car stereos only take MP3.`,
    `O M4A é um ficheiro de áudio MPEG-4, normalmente AAC, usado pelo iTunes, pelos memorandos de voz do iPhone e por muitos gravadores. Soa bem mesmo com tamanhos pequenos, mas alguns leitores e autorrádios só aceitam MP3.`],
  [`WAV audio`, `Áudio WAV`],
  [`WAV is uncompressed audio (usually PCM) used for recording and editing. It sounds exactly like the source but takes about 10 MB per minute in CD quality.`,
    `O WAV é áudio sem compressão (normalmente PCM) usado em gravação e edição. Soa exatamente como a origem, mas ocupa cerca de 10 MB por minuto em qualidade de CD.`],
  [`FLAC lossless audio`, `Áudio FLAC sem perdas`],
  [`FLAC is lossless compressed audio: it shrinks files to roughly half the size of WAV without losing any quality, which makes it the favourite format for music libraries and hi-res downloads.`,
    `O FLAC é áudio comprimido sem perdas: reduz os ficheiros para cerca de metade do tamanho do WAV sem perder qualquer qualidade, o que faz dele o formato preferido para bibliotecas de música e transferências em alta resolução.`],

  // Subtitles
  [`Subtitles`, `Legendas`],
  [`subtitles`, `legendas`],
  [`SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML and MicroDVD into each other without any engine, saved as UTF-8; SSA and SCC are read. Korean SMI and SRT files in CP949 are read correctly. Subtitles in a video come out with FFmpeg.`,
    `SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML e MicroDVD entre si, sem qualquer motor, guardados em UTF-8; SSA e SCC são lidos. Os ficheiros SMI e SRT coreanos em CP949 são lidos corretamente. As legendas dentro de um vídeo são extraídas com o FFmpeg.`],
  [`SubRip subtitles`, `Legendas SubRip`],
  [`SRT (SubRip) is the most common subtitle file: numbered cues with start and end times and plain text. Nearly every player, editor and video site accepts it.`,
    `O SRT (SubRip) é o ficheiro de legendas mais comum: blocos numerados com tempo de início e de fim e texto simples. Quase todos os leitores, editores e sites de vídeo o aceitam.`],
  [`Advanced SubStation Alpha subtitles`, `Legendas Advanced SubStation Alpha`],
  [`ASS (Advanced SubStation Alpha) is the styled subtitle format of anime fansubs and Aegisub, with fonts, colours, positions and effects. Many devices and sites only take plain SRT.`,
    `O ASS (Advanced SubStation Alpha) é o formato de legendas com estilos dos fansubs de anime e do Aegisub, com tipos de letra, cores, posições e efeitos. Muitos dispositivos e sites só aceitam SRT simples.`],
  [`WebVTT subtitles`, `Legendas WebVTT`],
  [`WebVTT (.vtt) is the subtitle format of HTML5 video. Web players, YouTube and online course platforms use it.`,
    `O WebVTT (.vtt) é o formato de legendas do vídeo HTML5. Usam-no os leitores Web, o YouTube e as plataformas de cursos online.`],
  [`SAMI subtitles (SMI)`, `Legendas SAMI (SMI)`],
  [`SAMI (.smi) is Microsoft's HTML-like subtitle format. It is still the classic subtitle file in Korea, often saved in the old CP949 encoding that newer players show as broken text.`,
    `O SAMI (.smi) é o formato de legendas da Microsoft, semelhante a HTML. Continua a ser o ficheiro de legendas clássico na Coreia, muitas vezes guardado na antiga codificação CP949, que os leitores mais recentes mostram como texto ilegível.`],

  // Archives
  [`Archives`, `Ficheiros comprimidos`],
  [`archives`, `ficheiros comprimidos`],
  [`Repack or extract ZIP, 7Z, RAR, TAR, disk images and many more archive formats with the bundled 7-Zip engine, or pack any files into one ZIP.`,
    `Recomprime ou extrai ZIP, 7Z, RAR, TAR, imagens de disco e muitos outros formatos de ficheiros comprimidos com o motor 7-Zip incluído, ou comprime quaisquer ficheiros num único ZIP.`],
  [`ZIP archive`, `Ficheiro ZIP`],
  [`ZIP is the universal archive format. Windows, macOS, phones and nearly every upload form open it without extra software.`,
    `O ZIP é o formato universal de ficheiros comprimidos. O Windows, o macOS, os telemóveis e quase todos os formulários de envio abrem-no sem programas adicionais.`],
  [`7-Zip archive`, `Ficheiro 7-Zip`],
  [`7Z is the open archive format of 7-Zip. Its LZMA2 compression usually makes smaller files than ZIP, but not every system or website can open it.`,
    `O 7Z é o formato aberto de ficheiros comprimidos do 7-Zip. A sua compressão LZMA2 cria normalmente ficheiros mais pequenos do que o ZIP, mas nem todos os sistemas ou sites o conseguem abrir.`],
  [`RAR archive`, `Ficheiro RAR`],
  [`RAR is the proprietary archive format of WinRAR, common for downloads split into parts. Recent Windows 11 versions can open RAR but can't create it, and many tools only accept ZIP.`,
    `O RAR é o formato proprietário de ficheiros comprimidos do WinRAR, comum em transferências divididas em partes. As versões recentes do Windows 11 abrem RAR, mas não o conseguem criar, e muitas ferramentas só aceitam ZIP.`],
  [`Any files`, `Quaisquer ficheiros`],

  // CAD
  [`CAD drawings`, `Desenhos CAD`],
  [`CAD drawings [in running text]`, `desenhos CAD`],
  [`AutoCAD DWG and DXF: convert between them or to PDF, SVG and PNG, without AutoCAD.`,
    `DWG e DXF do AutoCAD: converte entre ambos ou para PDF, SVG e PNG, sem o AutoCAD.`],
  [`AutoCAD drawing`, `Desenho do AutoCAD`],
  [`DWG is AutoCAD's native drawing format and the most common CAD file in architecture and engineering. Without AutoCAD or a DWG viewer it is hard to open or share.`,
    `O DWG é o formato de desenho nativo do AutoCAD e o ficheiro CAD mais comum em arquitetura e engenharia. Sem o AutoCAD ou um visualizador de DWG, é difícil abri-lo ou partilhá-lo.`],
  [`Drawing Exchange Format`, `Formato de intercâmbio de desenhos`],
  [`DXF (Drawing Exchange Format) is Autodesk's interchange format for CAD drawings. Laser cutters, CNC software and most CAD programs read it, so it is the usual way to move drawings between tools.`,
    `O DXF (Drawing Exchange Format) é o formato de intercâmbio da Autodesk para desenhos CAD. As máquinas de corte a laser, o software CNC e a maioria dos programas CAD leem-no, pelo que é a forma habitual de passar desenhos de uma ferramenta para outra.`],

  // 3D
  [`3D models`, `Modelos 3D`],
  [`3D models [in running text]`, `modelos 3D`],
  [`GLB, glTF, STL, OBJ, 3MF and PLY into each other, and FBX into any of them, with colours, textures and materials where the format keeps them, and to a shaded PNG or JPG picture. Nothing to install.`,
    `GLB, glTF, STL, OBJ, 3MF e PLY entre si, e FBX para qualquer um deles, com cores, texturas e materiais quando o formato os mantém, e para uma imagem PNG ou JPG sombreada. Nada para instalar.`],
  [`glTF binary (GLB)`, `glTF binário (GLB)`],
  [`GLB is the one-file version of glTF, the 3D format of the web, AR and game engines. Meshes, materials and textures are packed into a single compact file.`,
    `O GLB é a versão num só ficheiro do glTF, o formato 3D da Web, da realidade aumentada e dos motores de jogos. As malhas, os materiais e as texturas ficam reunidos num único ficheiro compacto.`],
  [`STL 3D model`, `Modelo 3D STL`],
  [`STL is the classic file for 3D printing. It stores only the triangles of a shape, with no colours or units, and every slicer and CAD program reads it.`,
    `O STL é o ficheiro clássico para impressão 3D. Guarda só os triângulos de uma forma, sem cores nem unidades, e todos os slicers e programas CAD o leem.`],
  [`Wavefront OBJ model`, `Modelo Wavefront OBJ`],
  [`OBJ (Wavefront) is a plain-text 3D format almost every 3D program opens. Materials and textures sit next to it in an .mtl file and pictures.`,
    `O OBJ (Wavefront) é um formato 3D em texto simples que quase todos os programas 3D abrem. Os materiais e as texturas ficam ao lado, num ficheiro .mtl e em imagens.`],

  // Fonts
  [`Fonts`, `Tipos de letra`],
  [`fonts`, `tipos de letra`],
  [`Desktop and web fonts: TTF, OTF, WOFF, WOFF2 and EOT into each other.`,
    `Tipos de letra para computador e para a Web: TTF, OTF, WOFF, WOFF2 e EOT entre si.`],
  [`TrueType font`, `Tipo de letra TrueType`],
  [`TTF (TrueType) is the most common desktop font format on Windows and macOS. Install it to use the font in any app.`,
    `O TTF (TrueType) é o formato de tipo de letra para computador mais comum no Windows e no macOS. Instala-o para usares o tipo de letra em qualquer aplicação.`],
  [`OpenType font`, `Tipo de letra OpenType`],
  [`OTF (OpenType) is a font format by Adobe and Microsoft. OpenType fonts with PostScript (CFF) outlines are common for professional typefaces and support features such as ligatures.`,
    `O OTF (OpenType) é um formato de tipo de letra da Adobe e da Microsoft. Os tipos de letra OpenType com contornos PostScript (CFF) são comuns em famílias tipográficas profissionais e suportam funcionalidades como as ligaturas.`],
  [`Web font (WOFF2)`, `Tipo de letra para a Web (WOFF2)`],
  [`WOFF2 is the compressed web font format supported by all modern browsers. It is typically about 30 % smaller than WOFF, so pages load faster.`,
    `O WOFF2 é o formato comprimido de tipos de letra para a Web suportado por todos os navegadores modernos. Costuma ser cerca de 30% mais pequeno do que o WOFF, pelo que as páginas carregam mais depressa.`],

  // Geospatial
  [`Geospatial data`, `Dados geoespaciais`],
  [`geospatial data`, `dados geoespaciais`],
  [`Maps and GPS data: GeoJSON, KML, KMZ, GPX and Shapefile into each other and to CSV, Excel and JSON, and a CSV with coordinates back into a map file. Vector data only (points, lines and areas), always saved in longitude and latitude. Nothing to install.`,
    `Mapas e dados de GPS: GeoJSON, KML, KMZ, GPX e Shapefile entre si e para CSV, Excel e JSON, e um CSV com coordenadas de volta para um ficheiro de mapa. Apenas dados vetoriais (pontos, linhas e áreas), sempre guardados em longitude e latitude. Nada para instalar.`],
  [`one row per feature, with its coordinates`, `uma linha por elemento, com as coordenadas`],
  [`a CSV with longitude and latitude columns or WKT`, `um CSV com colunas de longitude e latitude ou WKT`],

  // Camera RAW
  [`Camera RAW photo`, `Fotografia RAW de câmara`],
  [`Camera RAW files (CR2, CR3, NEF, ARW, DNG, RAF, ORF and more) hold the unprocessed sensor data of a photo. They keep the most detail for editing but are large and need special software to view.`,
    `Os ficheiros RAW de câmara (CR2, CR3, NEF, ARW, DNG, RAF, ORF e outros) guardam os dados em bruto do sensor de uma fotografia. Preservam o máximo de detalhe para edição, mas são grandes e precisam de um programa específico para serem visualizados.`],

  // Conversion guides
  [`JPG is the safe choice when a website, an older Windows app or someone without an iPhone needs your photos. A whole batch of HEIC photos converts at once, and each JPG is saved next to its original.`,
    `O JPG é a escolha segura quando um site, uma aplicação antiga do Windows ou alguém sem iPhone precisa das tuas fotografias. Um lote inteiro de fotografias HEIC é convertido de uma só vez, e cada JPG é guardado junto ao original.`],
  [`Choose PNG when you want to keep editing the photo without adding a round of JPG compression. PNG is lossless, so expect files several times larger than the HEIC original.`,
    `Escolhe PNG quando quiseres continuar a editar a fotografia sem acrescentar mais uma ronda de compressão JPG. O PNG não tem perdas, por isso conta com ficheiros várias vezes maiores do que o HEIC original.`],

  // Conversion guides
  [`HEIC keeps a photo in about half the space of a JPG at the same quality, the way iPhones save photos. Saving HEIC needs the free FFmpeg engine (about 100 MB, downloaded once in the app). EXIF, the colour profile and the orientation are kept.`,
    `O HEIC guarda uma fotografia em cerca de metade do espaço de um JPG com a mesma qualidade, tal como os iPhones guardam as fotografias. Guardar em HEIC requer o motor gratuito FFmpeg (cerca de 100 MB, descarregado uma única vez na aplicação). O EXIF, o perfil de cor e a orientação são mantidos.`],
  [`Images saved from websites are often WebP. Converting to PNG keeps the full quality and any transparency, so the result works in every editor, slide deck and document.`,
    `As imagens guardadas de sites estão muitas vezes em WebP. Converter para PNG mantém toda a qualidade e qualquer transparência, pelo que o resultado funciona em qualquer editor, apresentação e documento.`],
  [`Pick JPG when the image is a photo and file size matters, for example for upload forms that reject WebP.`,
    `Escolhe JPG quando a imagem for uma fotografia e o tamanho do ficheiro importar, por exemplo, em formulários de envio que recusam WebP.`],
  [`Screenshots and exported photos saved as PNG can be many megabytes. Photos usually get much smaller as JPG; for text-heavy screenshots and logos, PNG often stays the better format.`,
    `As capturas de ecrã e as fotografias exportadas em PNG podem ter muitos megabytes. As fotografias ficam normalmente muito mais pequenas em JPG; para capturas de ecrã com muito texto e para logótipos, o PNG continua muitas vezes a ser o melhor formato.`],
  [`Converting JPG to PNG doesn't bring back detail lost to JPG compression, but it stops further loss: every later edit and save stays lossless. Convert before you retouch an image or add transparency in an editor.`,
    `Converter JPG para PNG não recupera o detalhe perdido na compressão JPG, mas impede novas perdas: cada edição e gravação posterior fica sem perdas. Converte antes de retocares uma imagem ou de lhe acrescentares transparência num editor.`],
  [`AVIF images from modern websites and phones don't open in many older programs, image viewers and upload forms. JPG opens everywhere, at the cost of somewhat larger files.`,
    `As imagens AVIF de sites modernos e de telemóveis não abrem em muitos programas antigos, visualizadores de imagens e formulários de envio. O JPG abre em todo o lado, à custa de ficheiros um pouco maiores.`],
  [`WebP is ideal for websites: photos get much smaller than JPG and graphics keep their transparency. The WEBP preset saves at quality 85, a good balance for the web.`,
    `O WebP é ideal para sites: as fotografias ficam muito mais pequenas do que em JPG e os gráficos mantêm a transparência. A predefinição WEBP guarda com qualidade 85, um bom equilíbrio para a Web.`],
  [`Scanned pages, receipts and photos of documents often have to be sent as one PDF. Drop the images on the merge preset to get a single PDF, or on PDF to get one PDF per image. By default each page takes the size of its image.`,
    `Páginas digitalizadas, recibos e fotografias de documentos têm muitas vezes de ser enviados num único PDF. Larga as imagens na predefinição Juntar PDF para obteres um só PDF, ou em PDF para obteres um PDF por imagem. Por omissão, cada página fica com o tamanho da respetiva imagem.`],
  [`One ICO covers everything Windows needs for desktop, Explorer and taskbar icons, and it works as a website favicon too. Start from a square PNG of at least 256×256 px for the sharpest result.`,
    `Um único ICO cobre tudo o que o Windows precisa para os ícones do ambiente de trabalho, do Explorador e da barra de tarefas, e também serve de favicon de um site. Parte de um PNG quadrado com pelo menos 256×256 px para obteres o resultado mais nítido.`],
  [`Making a Mac app icon on Windows usually needs extra tools; Filee turns a PNG into an ICNS file directly. Use a square 1024×1024 px PNG so the Retina sizes stay sharp.`,
    `Criar um ícone de aplicação para Mac no Windows exige normalmente ferramentas adicionais; o Filee transforma um PNG num ficheiro ICNS diretamente. Usa um PNG quadrado de 1024×1024 px para que os tamanhos Retina fiquem nítidos.`],
  [`Share a Photoshop design with people who don't have Photoshop: the PNG shows the image as saved, with the visible layers combined and transparency kept. PNG can't store layers, so keep the PSD for editing.`,
    `Partilha um design do Photoshop com quem não tem o Photoshop: o PNG mostra a imagem tal como foi guardada, com as camadas visíveis combinadas e a transparência mantida. O PNG não guarda camadas, por isso mantém o PSD para editar.`],
  [`Filee reads the RAW files of Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One and more, and develops them with default settings. It's the quick way to get shareable JPGs from a shoot; for creative editing, use a RAW editor first.`,
    `O Filee lê os ficheiros RAW da Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One e outras, e revela-os com as definições de origem. É a forma rápida de obter JPG prontos a partilhar de uma sessão fotográfica; para edição criativa, usa primeiro um editor de RAW.`],
  [`Drop a whole memory card's worth of CR2 files at once: Filee converts them in parallel and saves each JPG next to its RAW file. Newer Canon cameras write CR3, which Filee reads as well.`,
    `Larga de uma só vez os CR2 de um cartão de memória inteiro: o Filee converte-os em paralelo e guarda cada JPG junto ao respetivo ficheiro RAW. As câmaras Canon mais recentes gravam CR3, que o Filee também lê.`],
  [`NEF files are too large and too unusual to send as they are. As JPG they become small, universally viewable photos; use JPG 70 % or a half-size preset for messaging apps. Nikon's NRW files from Coolpix cameras work the same way.`,
    `Os ficheiros NEF são demasiado grandes e invulgares para enviar tal como estão. Em JPG, passam a fotografias pequenas que abrem em todo o lado; usa JPG 70% ou Tamanho 50% para aplicações de mensagens. Os ficheiros NRW das câmaras Coolpix da Nikon funcionam da mesma forma.`],
  [`Many apps, slide decks and upload forms don't accept SVG. Filee renders the vector drawing to a PNG with transparency; compressed SVGZ files work too.`,
    `Muitas aplicações, apresentações e formulários de envio não aceitam SVG. O Filee renderiza o desenho vetorial num PNG com transparência; os ficheiros SVGZ comprimidos também funcionam.`],
  [`SVG to PDF stays vector: lines and text remain sharp at any zoom and in print, and the file stays small. Handy for sending logos and diagrams to a print shop or putting them into documents.`,
    `De SVG para PDF, tudo continua vetorial: as linhas e o texto ficam nítidos com qualquer zoom e na impressão, e o ficheiro continua pequeno. Prático para enviar logótipos e diagramas para uma gráfica ou para os colocar em documentos.`],
  [`EPS can only be displayed by a PostScript interpreter; Filee uses Ghostscript for that. The PDF keeps the vector artwork, so it opens anywhere and still prints sharply. PostScript (.ps) files work the same way.`,
    `O EPS só pode ser mostrado por um interpretador de PostScript; o Filee usa o Ghostscript para isso. O PDF mantém a arte vetorial, pelo que abre em todo o lado e continua a sair nítido na impressão. Os ficheiros PostScript (.ps) funcionam da mesma forma.`],
  [`Every page becomes its own JPG, so a 10-page PDF gives you 10 images. Handy for chats, slides and social posts that accept images but not PDF.`,
    `Cada página passa a um JPG próprio, pelo que um PDF de 10 páginas dá 10 imagens. Prático para conversas, diapositivos e publicações em redes sociais que aceitam imagens, mas não PDF.`],
  [`PNG keeps text and lines crisp without JPG artefacts, which suits slides, diagrams, sheet music and pages you want to annotate or put into a presentation.`,
    `O PNG mantém o texto e as linhas nítidos, sem os artefactos do JPG, o que é adequado para diapositivos, diagramas, partituras e páginas que queiras anotar ou colocar numa apresentação.`],
  [`Filee turns the PDF into a Word document with real paragraphs instead of page pictures, so you can fix typos or reuse the text. Complex layouts may need touch-ups, and a scanned PDF that only contains page images has no text to extract.`,
    `O Filee transforma o PDF num documento do Word com parágrafos verdadeiros em vez de imagens das páginas, para poderes corrigir gralhas ou reaproveitar o texto. Disposições complexas podem precisar de retoques, e um PDF digitalizado que só contém imagens das páginas não tem texto para extrair.`],
  [`Filee goes PDF → Word → EPUB on its own, so the text reflows to fit a phone or an e-reader screen. It works best with PDFs that have real text in them. Headings come through as plain paragraphs, and scanned pages have no text to convert.`,
    `O Filee faz PDF → Word → EPUB por si só, para que o texto se ajuste ao ecrã de um telemóvel ou de um leitor de livros digitais. Funciona melhor com PDF que tenham texto verdadeiro. Os títulos passam como parágrafos simples, e as páginas digitalizadas não têm texto para converter.`],
  [`Filee takes the text of the PDF into a Word document, writes it as HWPX and then saves that as HWP, all with built-in engines. It works for PDFs with real text in them. Complex layouts may need touch-ups, and scanned pages have no text to take out.`,
    `O Filee passa o texto do PDF para um documento do Word, escreve-o como HWPX e depois guarda-o como HWP, tudo com motores integrados. Funciona com PDF que tenham texto verdadeiro. Disposições complexas podem precisar de retoques, e as páginas digitalizadas não têm texto para extrair.`],
  [`Filee turns the PDF into a Word document first and then into Markdown, keeping paragraphs, headings and bold text where it can tell them apart. Useful for notes, wikis or pasting the text into other tools. Scanned pages have no text to convert.`,
    `O Filee transforma o PDF primeiro num documento do Word e depois em Markdown, mantendo os parágrafos, os títulos e o negrito sempre que os consegue distinguir. Útil para notas, wikis ou para colar o texto noutras ferramentas. As páginas digitalizadas não têm texto para converter.`],
  [`Korean offices often need documents in Hangul format. Filee converts the PDF's text into an HWPX file you can open and edit in Hancom Hangul, without Hancom Office for the conversion; turn it into HWP afterwards if a form requires the old format.`,
    `Os serviços coreanos pedem muitas vezes documentos em formato Hangul. O Filee converte o texto do PDF num ficheiro HWPX que podes abrir e editar no Hancom Hangul, sem precisar do Hancom Office para a conversão; depois, transforma-o em HWP se um formulário exigir o formato antigo.`],
  [`Handy when a PDF has to be shown in PowerPoint or added to an existing deck: every page becomes a slide that looks exactly like the PDF, and the page's text waits in the speaker notes. The slides are pictures, so to change the wording convert the PDF to DOCX instead.`,
    `Prático quando um PDF tem de ser mostrado no PowerPoint ou acrescentado a uma apresentação existente: cada página passa a um diapositivo igual ao PDF, e o texto da página fica à espera nas notas do apresentador. Os diapositivos são imagens; para alterar o texto, converte antes o PDF para DOCX.`],
  [`No Microsoft Word or LibreOffice needed: Filee reads the DOCX itself and lays out the pages with headers, footers, tables and pictures. Drop several documents on the merge preset to combine them into one PDF.`,
    `Sem Microsoft Word nem LibreOffice: o Filee lê o DOCX por si só e compõe as páginas com cabeçalhos, rodapés, tabelas e imagens. Larga vários documentos na predefinição Juntar PDF para os reunires num só PDF.`],
  [`Old Word 97–2003 documents from archives, official forms or legacy systems become PDFs that open anywhere. The same engine also converts ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord and Apple Pages files.`,
    `Os documentos antigos do Word 97–2003 vindos de arquivos, formulários oficiais ou sistemas legados passam a PDF que abrem em todo o lado. O mesmo motor também converte ficheiros ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord e Apple Pages.`],
  [`Save e-mails as PDF for records, invoices or legal files: the PDF shows the sender, recipients, date, subject and message, and it opens anywhere without a mail app.`,
    `Guarda e-mails em PDF para registos, faturas ou processos jurídicos: o PDF mostra o remetente, os destinatários, a data, o assunto e a mensagem, e abre em todo o lado sem uma aplicação de e-mail.`],
  [`Filee renders HWP pages with rhwp, an open-source Hangul engine, so neither Hancom Office nor its approval dialog is involved. Useful for sending Korean documents to people who can't open HWP.`,
    `O Filee renderiza as páginas HWP com o rhwp, um motor Hangul de código aberto, sem envolver o Hancom Office nem a respetiva janela de aprovação. Útil para enviar documentos coreanos a pessoas que não conseguem abrir HWP.`],
  [`Turn a Hangul document into a Word file that colleagues abroad can edit. Text, paragraphs and tables are carried over; layouts with many floating objects are worth a quick check in Word.`,
    `Transforma um documento Hangul num ficheiro do Word que colegas no estrangeiro possam editar. O texto, os parágrafos e as tabelas passam para o novo ficheiro; as disposições com muitos objetos flutuantes merecem uma verificação rápida no Word.`],
  [`HWPX, the newer XML-based Hangul format, is converted like HWP: the built-in rhwp engine lays out the pages, fully offline. Handy for archiving HWPX forms from public institutions as PDF.`,
    `O HWPX, o formato Hangul mais recente baseado em XML, é convertido como o HWP: o motor integrado rhwp compõe as páginas, totalmente offline. Prático para arquivar em PDF formulários HWPX de instituições públicas.`],
  [`Some systems and newer workflows accept only HWPX. Filee converts binary HWP to HWPX with rhwp, without Hancom Office, and converts a whole batch of old documents in one go.`,
    `Alguns sistemas e fluxos de trabalho mais recentes só aceitam HWPX. O Filee converte HWP binário para HWPX com o rhwp, sem o Hancom Office, e converte um lote inteiro de documentos antigos de uma só vez.`],
  [`Older versions of Hangul and some submission portals still expect .hwp. Filee converts HWPX back to HWP with rhwp, so you don't have to open and re-save each file in Hangul.`,
    `As versões mais antigas do Hangul e alguns portais de submissão ainda esperam .hwp. O Filee converte HWPX de volta para HWP com o rhwp, para não teres de abrir e voltar a guardar cada ficheiro no Hangul.`],
  [`Filee's own HWPX writer carries the Word layout over: page size and margins, headers and footers with page numbers, tables with merged cells, borders and shading, text boxes, shapes and pictures. Every file it writes is checked with three independent HWPX readers in the tests.`,
    `O gerador HWPX próprio do Filee transfere a disposição do Word: o tamanho da página e as margens, os cabeçalhos e rodapés com números de página, as tabelas com células unidas, os limites e o sombreado, as caixas de texto, as formas e as imagens. Nos testes, cada ficheiro que produz é verificado com três leitores de HWPX independentes.`],
  [`For offices and forms that still ask for .hwp. Filee writes the Word document as HWPX with its own writer and converts that to HWP with rhwp, both built in, so Hancom Office isn't needed for the conversion.`,
    `Para serviços e formulários que ainda pedem .hwp. O Filee escreve o documento do Word como HWPX com o seu próprio gerador e converte-o para HWP com o rhwp, ambos integrados, pelo que o Hancom Office não é necessário para a conversão.`],
  [`Each page of the Word document becomes a JPG (Filee lays the document out as a PDF first), handy for posting a page online or sending a quick preview. Word isn't needed.`,
    `Cada página do documento do Word passa a um JPG (o Filee compõe primeiro o documento como PDF), prático para publicar uma página online ou enviar uma pré-visualização rápida. Não é preciso ter o Word.`],
  [`Each visible sheet becomes its own section, with number formats, fonts, fills, borders and merged cells as Excel shows them. Wide sheets are scaled to the page width like Excel's "Fit all columns on one page", and frozen header rows repeat on every page.`,
    `Cada folha visível passa a uma secção própria, com os formatos de número, os tipos de letra, os preenchimentos, os limites e as células unidas tal como o Excel os mostra. As folhas largas são ajustadas à largura da página, como em «Ajustar Todas as Colunas a Uma Página» do Excel, e as linhas de cabeçalho fixas repetem-se em todas as páginas.`],
  [`CSV holds a single table, so Filee writes one CSV per sheet. Cells are exported as values, ready for databases, scripts and import forms.`,
    `O CSV guarda uma única tabela, pelo que o Filee escreve um CSV por folha. As células são exportadas como valores, prontas para bases de dados, scripts e formulários de importação.`],
  [`An XLSX workbook can hold the formatting, formulas and extra sheets that CSV can't. Select all your CSV exports and drop them at once to get one workbook per file, without Excel's import dialog.`,
    `Um livro XLSX pode guardar a formatação, as fórmulas e as folhas adicionais que o CSV não admite. Seleciona todos os CSV que exportaste e larga-os de uma só vez para obteres um livro por ficheiro, sem a caixa de diálogo de importação do Excel.`],
  [`Upgrade old Excel 97–2003 workbooks without Excel or LibreOffice: the conversion is built in. XLSX files are usually smaller, can't carry macros and open in every current spreadsheet app.`,
    `Atualiza livros antigos do Excel 97–2003 sem o Excel nem o LibreOffice: a conversão é integrada. Os ficheiros XLSX são normalmente mais pequenos, não podem conter macros e abrem em todas as aplicações de folhas de cálculo atuais.`],
  [`Each slide becomes one PDF page at the slide's size, with text, shapes, pictures, tables and the master design. Handy for handing out decks or uploading them where PowerPoint files aren't accepted. Animations and speaker notes aren't part of the PDF.`,
    `Cada diapositivo passa a uma página de PDF com o tamanho do diapositivo, com o texto, as formas, as imagens, as tabelas e o design do modelo global. Prático para distribuir apresentações ou enviá-las onde os ficheiros do PowerPoint não são aceites. As animações e as notas do apresentador não fazem parte do PDF.`],
  [`Old PowerPoint 97–2003 decks become PDFs that anyone can open, print or upload. Keynote (.key), ODP and WPS (DPS) presentations are converted the same way.`,
    `As apresentações antigas do PowerPoint 97–2003 passam a PDF que qualquer pessoa pode abrir, imprimir ou enviar. As apresentações Keynote (.key), ODP e WPS (DPS) são convertidas da mesma forma.`],
  [`Every slide becomes a JPG, ready for social posts, thumbnails, chat messages or a video editor. Choose PNG instead if the slides have lots of small text.`,
    `Cada diapositivo passa a um JPG, pronto para publicações em redes sociais, miniaturas, mensagens de conversa ou um editor de vídeo. Escolhe antes PNG se os diapositivos tiverem muito texto pequeno.`],
  [`Headings, lists (including task lists), tables, code, quotes, links, images, footnotes and math are laid out on A4 pages, without Pandoc, LaTeX or a browser. A quick way to share notes and README files with people who don't read Markdown.`,
    `Os títulos, as listas (incluindo listas de tarefas), as tabelas, o código, as citações, as ligações, as imagens, as notas de rodapé e as fórmulas matemáticas são compostos em páginas A4, sem Pandoc, LaTeX nem navegador. Uma forma rápida de partilhar notas e ficheiros README com quem não lê Markdown.`],
  [`Built in, no Pandoc needed. Headings, lists, tables, links and footnotes carry over, so you can keep editing and restyling the document in Word.`,
    `Integrado, sem precisar do Pandoc. Os títulos, as listas, as tabelas, as ligações e as notas de rodapé mantêm-se, para poderes continuar a editar o documento e a mudar o seu estilo no Word.`],
  [`Plain text becomes a clean A4 PDF with one paragraph per line. Filee recognises UTF-8 and UTF-16 as well as legacy Korean (CP949) text files, so old logs and notes don't turn into garbled characters.`,
    `O texto simples passa a um PDF A4 limpo, com um parágrafo por linha. O Filee reconhece UTF-8 e UTF-16, bem como ficheiros de texto coreanos antigos (CP949), para que registos e notas antigos não se transformem em carateres ilegíveis.`],
  [`Save a web page or an HTML report as a PDF that looks the same everywhere and can be archived or printed. Filee converts .html files saved on your PC, and several of them can be merged into one PDF.`,
    `Guarda uma página Web ou um relatório HTML como um PDF que tem o mesmo aspeto em todo o lado e pode ser arquivado ou impresso. O Filee converte ficheiros .html guardados no teu computador, e vários deles podem ser juntos num só PDF.`],
  [`A PDF keeps a fixed page layout, which is handy for printing an e-book, reading it on a PC or sending it to a device without an EPUB reader.`,
    `Um PDF mantém uma disposição de página fixa, o que é prático para imprimir um livro digital, lê-lo no computador ou enviá-lo para um dispositivo sem leitor de EPUB.`],
  [`Move an old Kindle/Mobipocket library to EPUB so it opens in Apple Books, Google Play Books, Kobo and most reader apps. This direction is built in, so Calibre isn't needed.`,
    `Passa uma biblioteca antiga de Kindle/Mobipocket para EPUB, para que abra no Apple Books, no Google Play Livros, no Kobo e na maioria das aplicações de leitura. Este sentido é integrado, pelo que o Calibre não é necessário.`],
  [`The e-book tool Calibre writes the MOBI and AZW3 files. Current Kindles also accept EPUB through Send to Kindle, so MOBI is mainly useful for older Kindle devices and apps.`,
    `Quem escreve os ficheiros MOBI e AZW3 é o Calibre, uma ferramenta de livros digitais. Os Kindle atuais também aceitam EPUB através do Send to Kindle, pelo que o MOBI é útil sobretudo para dispositivos e aplicações Kindle mais antigos.`],
  [`Save the soundtrack of a lecture, concert or interview as an MP3 that plays everywhere: in the car, on an old player or in a transcription tool.`,
    `Guarda o som de uma aula, de um concerto ou de uma entrevista como um MP3 que se ouve em todo o lado: no carro, num leitor antigo ou numa ferramenta de transcrição.`],
  [`iPhone and Mac videos are MOV files. As MP4 they play on Android phones, smart TVs, older Windows apps and upload forms that reject MOV. The video and sound usually fit MP4 as they are, so Filee only rewraps them: no quality lost, HDR kept, done in seconds. The MP4 720p preset shrinks 4K clips for sharing.`,
    `Os vídeos do iPhone e do Mac são ficheiros MOV. Em MP4, são reproduzidos em telemóveis Android, smart TVs, aplicações antigas do Windows e formulários de envio que recusam MOV. O vídeo e o som cabem normalmente no MP4 tal como estão, pelo que o Filee só muda o contentor: sem perda de qualidade, com o HDR mantido e em poucos segundos. A predefinição MP4 720p reduz vídeos 4K para os partilhares.`],
  [`MKV recordings, for example from OBS, often won't import into video editors or play on TVs, while MP4 is accepted almost everywhere. The conversion runs locally, so long recordings never have to be uploaded.`,
    `As gravações em MKV, por exemplo do OBS, muitas vezes não podem ser importadas em editores de vídeo nem reproduzidas em televisores, enquanto o MP4 é aceite quase em todo o lado. A conversão é feita localmente, pelo que as gravações longas nunca têm de ser enviadas para a Internet.`],
  [`Screen recordings and videos saved from the browser are often WebM, which many video editors, older players and messaging apps handle poorly. MP4 plays almost everywhere, and a whole batch of clips converts at once.`,
    `As gravações de ecrã e os vídeos guardados a partir do navegador estão muitas vezes em WebM, um formato com que muitos editores de vídeo, leitores antigos e aplicações de mensagens lidam mal. O MP4 é reproduzido quase em todo o lado, e um lote inteiro de vídeos é convertido de uma só vez.`],
  [`Turn a short clip into an animated GIF for chats, documentation or bug reports. Keep it short: GIF stores every frame as a 256-colour image, so long or high-resolution videos make very large files.`,
    `Transforma um vídeo curto num GIF animado para conversas, documentação ou relatórios de erros. Mantém-no curto: o GIF guarda cada fotograma como uma imagem de 256 cores, pelo que os vídeos longos ou de alta resolução dão ficheiros muito grandes.`],
  [`A video dropped on JPG gives one still picture. To pick a thumbnail or go through a clip frame by frame, use the Extract frames (JPG) preset: the pictures land in a folder next to the video, every frame or every Nth. A video that would give more than 100,000 pictures or fill the disk is refused before it starts.`,
    `Um vídeo largado em JPG dá uma única imagem fixa. Para escolher uma miniatura ou percorrer um vídeo fotograma a fotograma, usa a predefinição Extrair fotogramas (JPG): as imagens vão para uma pasta junto ao vídeo, todos os fotogramas ou um a cada N. Um vídeo que daria mais de 100 000 imagens ou encheria o disco é recusado antes de começar.`],
  [`AVI files from old camcorders and cameras are large and often use codecs that phones and TVs no longer play. An MP4 with modern compression is usually much smaller and plays everywhere.`,
    `Os ficheiros AVI de câmaras de vídeo e máquinas fotográficas antigas são grandes e usam muitas vezes codecs que os telemóveis e televisores já não reproduzem. Um MP4 com compressão moderna é normalmente muito mais pequeno e é reproduzido em todo o lado.`],
  [`A WAV recording takes about 10 MB per minute; as MP3 it needs a fraction of that and still plays on every device.`,
    `Uma gravação WAV ocupa cerca de 10 MB por minuto; em MP3, precisa de uma fração disso e continua a ser reproduzida em qualquer dispositivo.`],
  [`Keep your lossless FLAC library at home and put MP3 copies on the phone, a USB stick for the car or an older player that doesn't play FLAC. Whole albums convert in one go.`,
    `Mantém a tua biblioteca FLAC sem perdas em casa e põe cópias em MP3 no telemóvel, numa pen USB para o carro ou num leitor antigo que não reproduza FLAC. Os álbuns inteiros são convertidos de uma só vez.`],
  [`iPhone voice memos, DRM-free iTunes downloads and many recorders produce M4A. MP3 is accepted by every player, car stereo and upload form.`,
    `Os memorandos de voz do iPhone, as transferências do iTunes sem DRM e muitos gravadores produzem M4A. O MP3 é aceite por todos os leitores, autorrádios e formulários de envio.`],
  [`Repack RAR archives as ZIP for people, upload forms and systems that only accept ZIP. WinRAR isn't needed, neither to read the RAR nor to write the ZIP.`,
    `Recomprime ficheiros RAR em ZIP para pessoas, formulários de envio e sistemas que só aceitam ZIP. Não é preciso ter o WinRAR, nem para ler o RAR nem para escrever o ZIP.`],
  [`7Z often compresses better, but ZIP opens on any computer or phone without extra software. Convert when you send an archive to someone who doesn't have 7-Zip.`,
    `O 7Z costuma comprimir melhor, mas o ZIP abre em qualquer computador ou telemóvel sem programas adicionais. Converte quando enviares um ficheiro comprimido a alguém que não tenha o 7-Zip.`],
  [`Send drawings to clients, site teams or print shops who don't have AutoCAD: a PDF opens on any PC or phone. Several drawings can be merged into one PDF.`,
    `Envia desenhos a clientes, equipas de obra ou gráficas que não tenham o AutoCAD: um PDF abre em qualquer computador ou telemóvel. Vários desenhos podem ser juntos num só PDF.`],
  [`DXF files from CAD programs, laser-cutting jobs or design exchanges become PDFs anyone can open and print. SVG and PNG are available too, for example for web previews.`,
    `Os ficheiros DXF de programas CAD, trabalhos de corte a laser ou trocas de projetos passam a PDF que qualquer pessoa pode abrir e imprimir. Também há SVG e PNG, por exemplo, para pré-visualizações na Web.`],
  [`DXF is the interchange format that laser cutters, CNC software and most CAD programs read. Converting DWG to DXF lets you open AutoCAD drawings in those tools, and DXF back to DWG works too.`,
    `O DXF é o formato de intercâmbio que as máquinas de corte a laser, o software CNC e a maioria dos programas CAD leem. Converter DWG para DXF permite abrir desenhos do AutoCAD nessas ferramentas, e de DXF de volta para DWG também funciona.`],
  [`Self-host a font on your website: WOFF2 is the compressed web font format every modern browser supports, typically about 30 % smaller than WOFF. Check that the font's license allows web embedding.`,
    `Aloja um tipo de letra no teu próprio site: o WOFF2 é o formato comprimido de tipos de letra para a Web que todos os navegadores modernos suportam, normalmente cerca de 30% mais pequeno do que o WOFF. Confirma que a licença do tipo de letra permite a incorporação na Web.`],
  [`Some older programs, cutting and embroidery machines and game engines only accept TrueType fonts. Convert a whole OTF font family to TTF in one go, without a font editor.`,
    `Alguns programas antigos, máquinas de corte e de bordar e motores de jogos só aceitam tipos de letra TrueType. Converte uma família inteira de tipos de letra OTF para TTF de uma só vez, sem um editor de tipos de letra.`],
  [`Use Line art to SVG for logos, signatures and scans: the ink becomes one black shape on a transparent background. Trace to SVG keeps up to 64 colours for icons and illustrations. Photos come out as flat patches, so tracing suits drawings best.`,
    `Usa Traços para SVG para logótipos, assinaturas e digitalizações: a tinta passa a uma única forma preta sobre fundo transparente. Vetorizar para SVG mantém até 64 cores para ícones e ilustrações. As fotografias saem como manchas de cor lisa, pelo que a vetorização resulta melhor com desenhos.`],
  [`A JPG of a logo or a scanned sketch becomes an SVG that stays sharp at any size, ready for a cutting plotter, a website or a print shop. JPG noise turns into specks, so lower the Detail setting in the preset if the result looks busy.`,
    `Um JPG de um logótipo ou de um esboço digitalizado passa a um SVG que fica nítido em qualquer tamanho, pronto para um plotter de corte, um site ou uma gráfica. O ruído do JPG transforma-se em pontinhos, por isso baixa a opção Detalhe na predefinição se o resultado parecer carregado.`],
  [`Laser cutters, CNC software and CAD programs read DXF. Filee writes the SVG's outlines in millimetres, so a shape 100 mm wide stays 100 mm. Curves become fine polylines. Fills, images and filters are left out.`,
    `As máquinas de corte a laser, o software CNC e os programas CAD leem DXF. O Filee escreve os contornos do SVG em milímetros, pelo que uma forma com 100 mm de largura continua com 100 mm. As curvas passam a polilinhas finas. Os preenchimentos, as imagens e os filtros ficam de fora.`],
  [`E-mails dragged out of Outlook are MSG files that only Outlook opens. As PDF they keep the sender, recipients, date, subject and message, and open anywhere. Outlook isn't needed.`,
    `Os e-mails arrastados para fora do Outlook são ficheiros MSG que só o Outlook abre. Em PDF, mantêm o remetente, os destinatários, a data, o assunto e a mensagem, e abrem em todo o lado. Não é preciso ter o Outlook.`],
  [`YAML is easier to read and edit by hand, which is why config files use it. Keys keep their order, and text that would read back as a number or true/false is quoted.`,
    `O YAML é mais fácil de ler e de editar à mão, e é por isso que é usado em ficheiros de configuração. As chaves mantêm a ordem, e o texto que seria lido de volta como número ou como true/false fica entre aspas.`],
  [`Turn a config file into JSON for an API, a script or a tool that only reads JSON. Anchors and aliases are resolved, and a file with several documents becomes one array. Comments are dropped, since JSON has none.`,
    `Transforma um ficheiro de configuração em JSON para uma API, um script ou uma ferramenta que só lê JSON. As âncoras e os aliases são resolvidos, e um ficheiro com vários documentos passa a um único array. Os comentários são descartados, uma vez que o JSON não os tem.`],
  [`A JSON list of records becomes a table you can open in Excel: one row per record, one column per key. A wrapper like {"users": […]} is looked through. Data that isn't a table stops with a message instead of a broken file.`,
    `Uma lista de registos em JSON passa a uma tabela que podes abrir no Excel: uma linha por registo, uma coluna por chave. Se os registos estiverem dentro de um invólucro como {"users": […]}, o Filee encontra-os. Os dados que não formam uma tabela param com uma mensagem, em vez de darem um ficheiro danificado.`],
  [`Get an address book into Excel or a mailing tool: one row per contact with name, organization, email, phone, address and birthday. Contacts from old Korean phones in CP949 are read correctly.`,
    `Leva uma lista de contactos para o Excel ou para uma ferramenta de envio de e-mails em massa: uma linha por contacto, com nome, organização, e-mail, telefone, morada e data de aniversário. Os contactos de telemóveis coreanos antigos em CP949 são lidos corretamente.`],
  [`Web players and online course platforms want WebVTT. Timing, line breaks and italics come across, and no engine is needed.`,
    `Os leitores Web e as plataformas de cursos online pedem WebVTT. Os tempos, as quebras de linha e o itálico mantêm-se, e não é preciso nenhum motor.`],
  [`Many players, TVs and editors don't read SMI, and old Korean SMI files often show as broken text. Filee detects CP949, picks the language with the most lines and saves a clean UTF-8 SRT.`,
    `Muitos leitores, televisores e editores não leem SMI, e os ficheiros SMI coreanos antigos aparecem muitas vezes com texto ilegível. O Filee deteta CP949, escolhe o idioma com mais linhas e guarda um SRT limpo em UTF-8.`],
  [`When a TV, a phone or a video site refuses styled ASS subtitles, plain SRT works. Bold, italics, underline and colours are kept; positions, fonts and effects are dropped.`,
    `Quando um televisor, um telemóvel ou um site de vídeos recusa legendas ASS com estilos, o SRT simples funciona. O negrito, o itálico, o sublinhado e as cores mantêm-se; as posições, os tipos de letra e os efeitos são descartados.`],
  [`Take the subtitles out of a film to edit or translate them. The first text subtitle track is saved as SRT; picture-based subtitles (DVD, Blu-ray) can't be turned into text. Needs the free FFmpeg engine.`,
    `Tira as legendas de um filme para as editares ou traduzires. A primeira faixa de legendas em texto é guardada como SRT; as legendas em imagem (DVD, Blu-ray) não podem ser convertidas em texto. Requer o motor gratuito FFmpeg.`],
  [`Open a print file in a 3D program that prefers OBJ. STL has no units, so Filee reads it as millimetres and writes OBJ in millimetres too, with Y pointing up like most 3D programs.`,
    `Abre um ficheiro de impressão 3D num programa 3D que prefira OBJ. O STL não tem unidades, pelo que o Filee o lê em milímetros e escreve o OBJ também em milímetros, com o eixo Y a apontar para cima, como na maioria dos programas 3D.`],
  [`Slicers for 3D printers take STL. Faces of any shape are split into triangles, and Y-up becomes Z-up, so an upright model stands on the print bed. STL keeps only the shape, so colours and textures stay in the OBJ.`,
    `Os slicers das impressoras 3D usam STL. As faces de qualquer forma são divididas em triângulos, e o Y para cima passa a Z para cima, para que um modelo na vertical fique de pé na base de impressão. O STL guarda só a forma, pelo que as cores e as texturas ficam no OBJ.`],
  [`Bring a model from the web or a game engine into a program that reads OBJ. The .mtl file and the textures are written next to the .obj, so keep them together.`,
    `Leva um modelo da Web ou de um motor de jogos para um programa que leia OBJ. O ficheiro .mtl e as texturas são escritos junto ao .obj, por isso mantém-nos juntos.`],

  // FAQ
  [`Is Filee really free?`,
    `O Filee é mesmo gratuito?`],
  [`Yes. Filee is free and open source under the MIT license: no ads, no watermarks, no account, no trial and no file-count or file-size limits of its own.`,
    `Sim. O Filee é gratuito e de código aberto, ao abrigo da licença MIT: sem anúncios, sem marcas de água, sem conta, sem período experimental e sem limites próprios de número ou de tamanho de ficheiros.`],
  [`Does it work offline? Are my files uploaded?`,
    `Funciona offline? Os meus ficheiros são enviados para a Internet?`],
  [`Every conversion runs on your own PC and files are never uploaded. The internet is only used to download an optional engine or check for updates, so confidential documents, photos and recordings stay on your computer.`,
    `Todas as conversões são feitas no teu próprio computador, e os ficheiros nunca são enviados. A Internet só é usada para descarregar um motor opcional ou procurar atualizações, pelo que os documentos confidenciais, as fotografias e as gravações ficam no teu computador.`],
  [`Which file formats does Filee support?`,
    `Que formatos de ficheiro suporta o Filee?`],
  [`Filee reads {formatTotal} file formats in {categoryCount} categories: {categoryList}. {builtinTotal} of them work right after install; the others use a free optional engine. The format catalog lists every format and what it converts to.`,
    `O Filee lê {formatTotal} formatos de ficheiro em {categoryCount} categorias: {categoryList}. {builtinTotal} deles funcionam logo após a instalação; os restantes usam um motor opcional gratuito. O catálogo de formatos lista cada formato e os formatos para que converte.`],
  [`Do I need Microsoft Office, Hancom Office or LibreOffice?`,
    `Preciso do Microsoft Office, do Hancom Office ou do LibreOffice?`],
  [`No. Word, Excel and PowerPoint files (DOCX, XLSX, XLS, CSV, PPTX) and Korean HWP/HWPX documents are converted by engines built into Filee. Filee doesn't use Office or Hancom Office even when they are installed; LibreOffice is only an optional in-app download for older formats such as DOC, PPT, ODT and RTF.`,
    `Não. Os ficheiros do Word, Excel e PowerPoint (DOCX, XLSX, XLS, CSV, PPTX) e os documentos coreanos HWP/HWPX são convertidos por motores integrados no Filee. O Filee não usa o Office nem o Hancom Office, mesmo que estejam instalados; o LibreOffice é apenas uma transferência opcional dentro da aplicação para formatos mais antigos, como DOC, PPT, ODT e RTF.`],
  [`What are the optional engines?`,
    `O que são os motores opcionais?`],
  [`Large engines are not in the installer. Tick them on the installer's engine page, or download them inside Filee whenever you need them: {engineDetails}. They are saved in Filee's own folder and can be removed at any time, and the app shows their versions, download speed and time left. If FFmpeg, calibre, Pandoc, Ghostscript or LibreOffice is already on your PC (on the PATH, Scoop included, or in Program Files), Filee uses it and skips the download, and says when that copy is older than the version it is tested with. Settings → Engines → Use my copy picks a specific one.`,
    `Os motores grandes não vêm no instalador. Seleciona-os na página de motores do instalador ou descarrega-os dentro do Filee sempre que precisares: {engineDetails}. Ficam guardados na pasta do próprio Filee e podem ser removidos a qualquer momento, e a aplicação mostra as versões, a velocidade de transferência e o tempo restante. Se o FFmpeg, o calibre, o Pandoc, o Ghostscript ou o LibreOffice já estiver no teu computador (no PATH, incluindo pelo Scoop, ou em Program Files), o Filee usa essa cópia e salta a transferência, e avisa quando essa cópia é mais antiga do que a versão com que o Filee é testado. Em Definições → Motores → Utilizar a minha cópia, escolhes uma cópia específica.`],
  [`Does installing Filee need administrator rights?`,
    `Instalar o Filee requer privilégios de administrador?`],
  [`Only once, while installing. The installer puts Filee in Program Files for all users and, on Windows 11, adds “Convert with Filee” to the top of the File Explorer menu. Filee itself then runs as your normal user. For silent installs, run the installer with /VERYSILENT /SUPPRESSMSGBOXES. If you can't install programs, use the portable ZIP: unzip it anywhere and run Filee.exe.`,
    `Só uma vez, durante a instalação. O instalador coloca o Filee em Program Files para todos os utilizadores e, no Windows 11, adiciona «Converter com o Filee» ao topo do menu do Explorador de Ficheiros. Depois disso, o Filee é executado com o teu utilizador normal. Para instalações silenciosas, executa o instalador com /VERYSILENT /SUPPRESSMSGBOXES. Se não puderes instalar programas, usa o ZIP portátil: extrai-o para qualquer pasta e executa o Filee.exe.`],
  [`Filee doesn't start on Windows 10: no window, no error. What can I do?`,
    `O Filee não arranca no Windows 10, sem janela nem erro. O que posso fazer?`],
  [`This happens on a Windows 10 that hasn't been updated for a long time, on a PC whose processor supports Hardware-enforced Stack Protection (CET). Windows turns that protection on but lacks a part that .NET needs, so Filee and its installer stop right away, without a window or a message. Installing the available Windows updates (the latest cumulative update) fixes it. If updating isn't possible, turning the protection off for Filee alone usually works: in PowerShell as administrator, run Set-ProcessMitigation -Name Filee.exe -Disable UserShadowStack, then the same for filee-cli.exe and for the installer's file name (or use the portable ZIP). To undo it, remove those entries in Windows Security → App & browser control → Exploit protection settings → Program settings.`,
    `Isto acontece num Windows 10 que não é atualizado há muito tempo, num computador cujo processador suporta a proteção de pilha imposta por hardware (CET). O Windows ativa essa proteção, mas falta-lhe uma parte de que o .NET precisa, pelo que o Filee e o instalador fecham de imediato, sem janela nem mensagem. Instalar as atualizações disponíveis do Windows (a atualização cumulativa mais recente) resolve o problema. Se não for possível atualizar, desativar a proteção só para o Filee costuma funcionar: no PowerShell como administrador, executa Set-ProcessMitigation -Name Filee.exe -Disable UserShadowStack e depois o mesmo para filee-cli.exe e para o nome do ficheiro do instalador (ou usa o ZIP portátil). Para anular, remove essas entradas em Segurança do Windows → Controlo de aplicações e browser → Definições de proteção contra exploits → Definições do programa.`],
  [`Can I convert many files at once?`,
    `Posso converter muitos ficheiros de uma só vez?`],
  [`Yes. Select as many files as you like and drop them once: Filee converts them in parallel, a failed file never stops the others, and presets can merge everything into one PDF or pack it into one ZIP.`,
    `Sim. Seleciona os ficheiros que quiseres e larga-os de uma só vez: o Filee converte-os em paralelo, um ficheiro que falhe nunca interrompe os outros, e as predefinições podem juntar tudo num só PDF ou comprimir tudo num só ZIP.`],
  [`Can I convert from the Windows 11 right-click menu?`,
    `Posso converter a partir do menu de contexto do Windows 11?`],
  [`Yes. Right-click files in File Explorer and choose "Convert with Filee". On Windows 11 you can also put it in the top-level menu, without "Show more options": click "Add to the main menu" in Settings → General once and approve the administrator prompt. Send To, a keyboard shortcut and the drop zone in the main window work too.`,
    `Sim. Clica com o botão direito nos ficheiros no Explorador de Ficheiros e escolhe «Converter com o Filee». No Windows 11, também podes pôr esta opção no menu principal, sem passar por «Mostrar mais opções»: clica uma vez em «Adicionar ao menu principal» em Definições → Geral e aprova o pedido de administrador. «Enviar para», um atalho de teclado e a zona de largada da janela principal também funcionam.`],
  [`Can Filee convert from the command line or automatically?`,
    `O Filee converte pela linha de comandos ou automaticamente?`],
  [`Yes. Setup can add the filee command to PATH: filee convert *.heic --to jpg converts files, wildcards and folders with your presets, prints JSON for scripts and returns exit codes. Watch folders automatically convert the files that land in a folder and can move the originals aside. Set them up on the Watch folders page in the app or with filee watch in a terminal.`,
    `Sim. O instalador pode adicionar o comando filee ao PATH: filee convert *.heic --to jpg converte ficheiros, carateres universais e pastas com as tuas predefinições, escreve JSON para scripts e devolve códigos de saída. As pastas monitorizadas convertem automaticamente os ficheiros que chegam a uma pasta e podem pôr os originais de lado. Configura-as na página Pastas monitorizadas da aplicação ou com filee watch num terminal.`],
  [`How do I convert a file, for example HEIC to JPG?`,
    `Como converto um ficheiro, por exemplo, de HEIC para JPG?`],
  [`Select the files in File Explorer, hold Ctrl (or the key you chose) and drag them. A donut of formats opens at the cursor: drop the files on JPG and the new files appear next to the originals. There are step-by-step guides for the most common conversions.`,
    `Seleciona os ficheiros no Explorador de Ficheiros, mantém Ctrl premido (ou a tecla que escolheste) e arrasta-os. Abre-se uma barra circular de formatos junto ao cursor: larga os ficheiros em JPG e os novos ficheiros aparecem junto aos originais. Há guias passo a passo para as conversões mais comuns.`],
  [`Why use Filee instead of an online converter?`,
    `Porquê usar o Filee em vez de um conversor online?`],
  [`Online converters upload your files to someone else's server, often limit file size and count, and depend on a fast connection. Filee converts on your PC: private files stay private, large videos and hundreds of files are no problem, and it works without internet, for free and without ads.`,
    `Os conversores online enviam os teus ficheiros para o servidor de outra pessoa, limitam muitas vezes o tamanho e o número de ficheiros e dependem de uma ligação rápida. O Filee converte no teu computador: os ficheiros privados continuam privados, os vídeos grandes e as centenas de ficheiros não são problema, e funciona sem Internet, de forma gratuita e sem anúncios.`],
  [`Which operating systems are supported?`,
    `Que sistemas operativos são suportados?`],
  [`Windows 10 and 11 (64-bit) and Linux (x64 and ARM64, Ubuntu 22.04 or later) are full releases. On Linux the drag gesture needs an X11 session; on KDE Plasma with Wayland it is experimental, and on other Wayland desktops the drop zone and the file manager's right-click menu work. macOS 13 or later (Apple silicon and Intel) is a preview: the app isn't notarized yet, so macOS asks you to allow it once under Privacy & Security. Pick your system in the download section.`,
    `O Windows 10 e 11 (64 bits) e o Linux (x64 e ARM64, Ubuntu 22.04 ou posterior) têm versões completas. No Linux, o gesto de arrastar precisa de uma sessão X11; no KDE Plasma com Wayland é experimental, e nos outros ambientes Wayland funcionam a zona de largada e o menu de contexto do gestor de ficheiros. O macOS 13 ou posterior (Apple silicon e Intel) é uma pré-visualização: a aplicação ainda não está notarizada, pelo que o macOS te pede que a autorizes uma vez em Privacidade e segurança. Escolhe o teu sistema na secção de transferência.`],
]);
